  private void heading(String title){LinearLayout r=row();TextView back=label("‹",30,GOLD,true);back.setPadding(0,0,dp(14),0);back.setContentDescription("Back to home");back.setOnClickListener(v->open("Home"));if(!"Home".equals(title))r.addView(back);TextView t=label(title.equals("Home")?"BIKI Billing PRO":title,22,INK,true);r.addView(t,new LinearLayout.LayoutParams(0,-2,1));TextView b=label("Lock",13,GOLD,true);b.setPadding(dp(10),dp(8),0,dp(8));b.setOnClickListener(v->lock());r.addView(b);body.addView(r);gap(body,8);body.addView(label("S I G N A T U R E   •   READ ONLY",10,GOLD,true));gap(body,18);}
  private JSONArray validSales(){JSONArray a=arr("sales"),out=new JSONArray();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&!o.optBoolean("v2Cancelled",false))out.put(o);}return out;}
