  private JSONArray arr(String k){JSONArray a=data==null?null:data.optJSONArray(k);return a==null?new JSONArray():a;}
  private double sum(JSONArray a,String field,String kind,String date){double total=0;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;if(kind!=null&&!kind.equals(o.optString("kind")))continue;if(date!=null&&!date.equals(o.optString("date")))continue;double v=o.optDouble(field,0);if(Double.isFinite(v))total+=v;}return total;}
