  private JSONArray nested(String parent,String key){JSONObject o=data==null?null:data.optJSONObject(parent);JSONArray a=o==null?null:o.optJSONArray(key);return a==null?new JSONArray():a;}
  private JSONArray filtered(JSONArray a,String k,String v){JSONArray out=new JSONArray();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&v.equalsIgnoreCase(o.optString(k)))out.put(o);}return out;}
  private JSONArray bankRecords(){JSONArray a=arr("transactions"),out=new JSONArray();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&o.optString("title").toLowerCase(Locale.ROOT).matches(".*(csp|bank|aeps|deposit|withdrawal).*"))out.put(o);}return out;}
